// BANK-FIX-1 PR-1 (2026-10-06) — the MUTATION LEDGER for the wrong-answer fixes.
// Authority for every finding: draft PR #960 (`ops/reports/bank-audit-1/wrong-answers.csv`).
//
// One entry per (surface, id) the audit flagged as wrong:
//   verdict "fixed"         — key / options / solution (and, where `stemChanged`, the stem)
//                             corrected in the row's own source file; re-solved by an
//                             INDEPENDENT pass (fresh context, never shown the key) that agreed
//                             with the corrected key — disagreements were fixed again (round 2).
//   verdict "withheld"      — could not be corrected without becoming a different question;
//                             added to WITHHELD_QUESTION_IDS.
//   verdict "flag-rejected" — the audit flag was wrong; the row was already correct (re-solved).
// `origin` is the audit's provenance class. Every fixed BANK row now carries
// `sourceOverride: "others"` (owner ruling 2): it is served, but never as PYQ / NCERT and never
// with a year. `originalPyqYear` / `originalPyqSet` keep the provenance the row used to claim.
// Pins (`bankFix1.pr1.test.ts`): `keyOptionIndex` — the 0-based option the stored key must
// resolve to (app resolver); `keyMustContain` — values the stored answer must carry.
// Row ids are never changed (Mistake Intelligence history keys on them).

export interface BankFix1Entry {
  id: string;
  surface: "bank" | "predicted" | "hpq";
  verdict: "fixed" | "withheld" | "flag-rejected";
  fields: readonly string[];
  stemChanged: boolean;
  origin: string;
  originalPyqYear?: string;
  originalPyqSet?: string;
  key: string;
  keyOptionIndex?: number;
  keyMustContain?: readonly string[];
  why: string;
}

