// ===== BANK-FIX-1 PR-2 (2026-10-07) — broken tagging, ambiguous keys, missing figures, fallback answers =====
//
// One entry per (surface, id) whose RUNTIME row this PR changed — measured, not declared: a dump of
// trunk 678b9811 (before) against this branch (after). `fields` are the runtime fields that differ.
//   verdict "fixed"          — content changed (stem / options / key / steps / explanation); every served
//                              one was re-solved by an INDEPENDENT solver that never saw the key
//                              (`resolve`): "agree" (blind batch), "agree-with-figure" (solver saw the bound
//                              image), "agree-after-refix" (re-fixed after a disagreement, then re-solved
//                              blind), "adjudicated" (solver differed; the adjudicator upheld the stored key).
//   verdict "re-tagged"      — marks / section / format / chapter / subtopic only (no content change).
//   verdict "re-sourced"     — only the source: `sourceOverride: "others"`, year / set / isPYQ removed.
//   verdict "answer-written" — a promptD fallback row that had NO answer now has one (re-solved).
//   verdict "withheld"       — no longer served (`category` = why); ids are kept in the withhold sets.
//   verdict "clone-removed"  — a promptD "-D2" drill clone of a seed row (the only rows removed).
// `others` = this PR filed the row under Others (owner ruling 2). `keyOptionIndex` = the 0-based option
// the independent solver chose, which the stored key must resolve to with the app's resolver.
// Pinned by bankFix1.pr2.test.ts. Row ids are never changed.

export interface BankFix1Pr2Entry {
  id: string;
  surface: "bank" | "predicted" | "hpq" | "promptD";
  verdict: "fixed" | "re-tagged" | "re-sourced" | "answer-written" | "withheld" | "clone-removed";
  fields: readonly string[];
  others: boolean;
  resolve?: "agree" | "agree-with-figure" | "agree-after-refix" | "adjudicated";
  keyOptionIndex?: number;
  category?: string;
  why: string;
}

